const{chromium}=require('playwright'),fs=require('fs');
(async()=>{const b=await chromium.launch({channel:'msedge',headless:true}),rows=[];try{for(const host of ['keycloak.nigeriag2p.com','g2p-keycloak.wverve.in','minio.nigeriag2p.com','g2p-minio.wverve.in','kafka.nigeriag2p.com','g2p-kafka.wverve.in']){const c=await b.newContext({ignoreHTTPSErrors:true}),p=await c.newPage();let row={host};try{const r=await p.goto('https://'+host+(host.includes('keycloak')?'/admin/':'/'),{timeout:18000,waitUntil:'domcontentloaded'});await p.waitForTimeout(1500);row.http=r.status();row.path=new URL(p.url()).pathname;row.title=await p.title();row.hasLogin=await p.locator('#username,input[type=password]').count();row.status=r.status()>=400?'RESTRICTED_OR_UNAVAILABLE':'REACHABLE_NOT_AUTHENTICATED';}catch(e){row.status='UNAVAILABLE';row.error=e.message.split('\n')[0].replace(/https?:\/\/\S+/g,'[URL omitted]');}rows.push(row);console.log(JSON.stringify(row));await c.close();}fs.writeFileSync('H:/Nigeria_Mosip/NSIPA-Private-Access-20261111/Console-Public-Routes.json',JSON.stringify(rows,null,2));}finally{await b.close()}})();
